  'e1649-flauros': { category: 'demon', rank: '무시무시한 표범 형상이나 불꽃 눈을 지닌 인간 모습으로 나타나 과거·현재·미래를 꿰뚫어 보고 20개 군단을 거느리는 지옥의 대장군. 루이 브르통의 68대 지옥 도판 중 제31번.', legions: 20, domains: ["솔로몬 72 악마","지옥의 대공","예언·적 말살","브르통 68 도판"] },
  'flauros': { category: 'demon', subCategory: 'duke', rank: '지옥의 대장군(Grand Général)', legions: 20, domains: ["솔로몬 72 악마","지옥의 대공","예언·적 말살","브르통 68 도판"] },
